import { useEffect, useMemo, useState } from 'react';
import { JxBadge, JxEmptyState, JxPagination, JxTable } from '@jinx-ui/react';

export interface User {
  id: string;
  name: string;
  role: string;
  active: boolean;
}

export interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));

  useEffect(() => {
    if (page > pageCount) setPage(pageCount);
  }, [page, pageCount]);

  const visible = useMemo(() => {
    const start = (page - 1) * PAGE_SIZE;
    return users.slice(start, start + PAGE_SIZE);
  }, [users, page]);

  if (users.length === 0) {
    return (
      <JxEmptyState
        title="Пользователей пока нет"
        message="Как только кого-нибудь пригласят в рабочее пространство, он появится в этом списке."
      />
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
      <JxTable>
        <thead>
          <tr>
            <th scope="col">Имя</th>
            <th scope="col">Роль</th>
            <th scope="col">Статус</th>
          </tr>
        </thead>
        <tbody>
          {visible.map((user) => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td style={{ color: 'var(--jx-text-2)' }}>{user.role}</td>
              <td>
                <JxBadge tone={user.active ? 'success' : 'danger'} dot>
                  {user.active ? 'Активен' : 'Отключён'}
                </JxBadge>
              </td>
            </tr>
          ))}
        </tbody>
      </JxTable>

      {pageCount > 1 && (
        <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
          <JxPagination total={pageCount} page={page} onPageChange={setPage} />
        </div>
      )}
    </div>
  );
}

